const appointment = $json.data;

if (!appointment?.id) {
  throw new Error(
    'Directus no devolvió appointment.id'
  );
}

if (
  !appointment.start_at ||
  !appointment.end_at
) {
  throw new Error(
    'Directus no devolvió las nuevas fechas'
  );
}

return [
  {
    json: {
      status: 'rescheduled',
      appointment
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const appointmentId = clean(
  input.appointment_id
);

const startAtRaw = clean(
  input.start_at
);

const endAtRaw = clean(
  input.end_at
);

if (!appointmentId) {
  throw new Error(
    'appointment_id es obligatorio'
  );
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(appointmentId)) {
  throw new Error(
    `appointment_id no es un UUID válido: ${appointmentId}`
  );
}

if (!startAtRaw) {
  throw new Error(
    'start_at es obligatorio'
  );
}

if (!endAtRaw) {
  throw new Error(
    'end_at es obligatorio'
  );
}

const startAt = new Date(startAtRaw);
const endAt = new Date(endAtRaw);

if (Number.isNaN(startAt.getTime())) {
  throw new Error(
    `start_at no es una fecha válida: ${startAtRaw}`
  );
}

if (Number.isNaN(endAt.getTime())) {
  throw new Error(
    `end_at no es una fecha válida: ${endAtRaw}`
  );
}

if (endAt.getTime() <= startAt.getTime()) {
  throw new Error(
    'end_at debe ser posterior a start_at'
  );
}

return [
  {
    json: {
      appointment_id: appointmentId,

      update: {
        start_at: startAt.toISOString(),
        end_at: endAt.toISOString()
      }
    }
  }
];
